"""Build an offline Hebrew listening workbench; human ratings stay separate."""
from pathlib import Path
import json
import pandas as pd
from synthetic_pilot import OUT

df=pd.read_csv(OUT/'analysis'/'sample_features.csv',keep_default_na=False)
metrics=json.loads((OUT/'analysis'/'key_metrics.json').read_text(encoding='utf-8'))
voices=pd.read_csv(OUT/'analysis'/'voice_summary.csv',keep_default_na=False)
fields=['sample_id','model','family','voice','voice_identity_group','text','wav_path','duration_s','rms_dbfs',
        'quiet_fraction_45dbfs','review_flag_count','review_reasons','language_qc_status',
        'provider_gender_label','provider_age_label','presentation_for_summary','perceived_age_band',
        'presentation_confidence','age_confidence','transcript','notes']
data={'samples':df[fields].to_dict('records'),'metrics':metrics,'voice_groups':voices.to_dict('records')}
payload=json.dumps(data,ensure_ascii=True).replace('</','< /')
template='''<!doctype html>
<html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>פיילוט קולות מסונתזים בעברית</title>
<style>
:root{font-family:"Segoe UI",Arial,sans-serif;color:#193042;background:#f1f5f8}*{box-sizing:border-box}body{margin:0}main{max-width:1450px;margin:auto;padding:28px}h1{margin:0 0 8px;font-size:30px}h2{font-size:22px}p{line-height:1.65}.muted{color:#5d6e7b}.banner{background:#fff7dc;border-right:5px solid #c99529;border-radius:8px;padding:14px 18px;margin:18px 0}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.stat,.panel,.card{background:white;border:1px solid #dae3e9;border-radius:12px;padding:18px}.stat strong{display:block;font-size:28px;color:#116778}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:18px 0;position:sticky;top:0;background:#f1f5f8ee;backdrop-filter:blur(8px);padding:12px 0;z-index:3}button,select,input,textarea{font:inherit;border:1px solid #c8d5df;border-radius:7px;padding:9px;background:white}button{cursor:pointer;background:#126b7d;color:white;border-color:#126b7d}button.secondary{background:white;color:#126b7d}.toolbar input{min-width:240px}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:15px}.card h3{margin:0 0 8px}.id{direction:ltr;unicode-bidi:embed;overflow-wrap:anywhere}.model{font-size:12px;color:#627684}.card audio{width:100%;margin:10px 0}.card label{display:block;font-size:14px;margin-top:10px}.card select,.card textarea{width:100%;margin-top:5px}.card textarea{min-height:58px}.small{font-size:13px}.pill{display:inline-block;border-radius:20px;background:#e8f4ef;color:#23664c;padding:3px 10px;font-size:12px}.pill.warn{background:#fff1d9;color:#805414}.saved{border-top:4px solid #32996a}details{margin-top:12px}summary{cursor:pointer}.plots{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px}.plots img{width:100%;height:auto;border:1px solid #d5e0e7;background:white}.pager{display:flex;gap:12px;align-items:center;justify-content:center;margin:20px}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border-bottom:1px solid #dce5eb;padding:9px;text-align:right}.notes{white-space:pre-wrap}.prompt{font-size:19px;background:#eaf3f6;padding:15px;border-radius:9px}a{color:#116778}.status{min-height:24px;color:#23664c}
</style></head><body><main>
<h1>קולות מסונתזים בעברית — האזנה, התפלגויות ותיוג</h1>
<p class="muted">דגימה אחת לכל צירוף מודל–קול. כל ההקלטות קוראות את אותו משפט בעברית. קולות מוכנים של הספקים; ללא שכפול קול.</p>
<div class="stats" id="stats"></div>
<p class="prompt" id="prompt"></p>
<div class="banner"><strong>איך לקרוא את נתוני הגיל והמגדר?</strong><br>תוויות הספק, הערכות מודל והתרשמות אנושית הן מקורות נפרדים. קול סינתטי אינו בעל גיל ביולוגי. המודל האוטומטי החזיר את אותה קטגוריית גיל לכל הדגימות, ולכן אומדן הגיל שלו אינו מוצג כהתפלגות גיל תקפה. אפשר לתייג כאן את טווח הגיל שהקול נשמע בו. הערכות המודל מוסתרות בכרטיסים עד לפתיחת הפרטים, כדי להפחית הטיה בהאזנה.</div>
<details class="panel"><summary><strong>התפלגויות ונתונים מסכמים</strong></summary>
<p>הספירה לפי מזהי קול מקבצת גרסאות של אותו קול. סתירה בין גרסאות נשארת גלויה ואינה מוכרעת בהצבעת רוב. אלו אומדנים אוטומטיים לא מאומתים, לא ספירה של נשים וגברים אמיתיים.</p>
<div class="plots">
<a href="analysis/figures/perceptual_voice_groups.png"><img src="analysis/figures/perceptual_voice_groups.png" alt="התרשמות קולית ואזהרת אומדן גיל"></a>
<a href="analysis/figures/provider_labels.png"><img src="analysis/figures/provider_labels.png" alt="תיאורי קול וגיל של הספקים וחוסרים"></a>
<a href="analysis/figures/model_audio_comparison.png"><img src="analysis/figures/model_audio_comparison.png" alt="משך ועוצמה לפי מודל"></a>
<a href="analysis/figures/real_synthetic_reference.png"><img src="analysis/figures/real_synthetic_reference.png" alt="השוואה תיאורית מול קטעים אנושיים קצרים"></a>
</div><div class="tablewrap" id="voiceTable"></div></details>
<h2>האזנה ותיוג אנושי</h2>
<p class="small muted">הבחירות נשמרות בדפדפן המקומי. כדי לשמור קובץ בפרויקט, לחץ על ״ייצוא תיוגים״ והעבר את הקובץ לבדיקה. שום תיוג לא נשלח לשרת ולא מחליף את נתוני הספק או המודל.</p>
<div class="toolbar"><select id="model"><option value="">כל המודלים</option></select><input id="search" placeholder="חיפוש קול או משפחה" aria-label="חיפוש קול"><select id="filter"><option value="all">כל הדגימות</option><option value="unrated">ללא תיוג אנושי שמור</option><option value="flagged">מסומנות לבדיקה</option></select><button id="export">ייצוא תיוגים</button><button class="secondary" id="importButton">טעינת תיוגים קודמים</button><input type="file" id="importFile" accept="application/json,.json" hidden></div>
<div class="status" id="status" role="status"></div><p id="count" class="muted"></p>
<div class="gallery" id="gallery"></div><div class="pager"><button id="previous" class="secondary">הקודם</button><span id="page"></span><button id="next" class="secondary">הבא</button></div>
<p class="small muted">בדיקת העברית היא בדיקה אוטומטית של תמלול והתאמה למשפט; היא עדיין מאפשרת תיקון אנושי. הניתוח המלא נמצא במחברת synthetic_eda.ipynb ובדוח SYNTHETIC_EDA_PROGRESS.md שבתיקיית הפרויקט.</p>
<script id="data" type="application/json">__PAYLOAD__</script>
<script>
const bundle=JSON.parse(document.getElementById('data').textContent), samples=bundle.samples;
const key='HebrewSyntheticPilotRatingsV1'; let ratings={};try{ratings=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}
let page=0;const size=24,ids=new Set(samples.map(s=>s.sample_id));
const presentation=[['','בחרו'],['masculine','קול נשמע גברי'],['feminine','קול נשמע נשי'],['androgynous','קול נשמע אנדרוגיני / ביניים'],['uncertain','לא בטוח']];
const ages=[['','בחרו'],['childlike','נשמע ילדי / נערי'],['young_adult_18_29','נשמע בוגר צעיר, בערך 18–29'],['adult_30_44','נשמע בערך 30–44'],['mature_45_59','נשמע בערך 45–59'],['older_60_plus','נשמע בערך 60 ומעלה'],['uncertain','לא בטוח']];
function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function selectField(card,title,field,options,s){const label=element('label',title),select=element('select');options.forEach(([value,text])=>{const option=element('option',text);option.value=value;select.appendChild(option)});select.value=(ratings[s.sample_id]||{})[field]||'';select.onchange=()=>save(s,field,select.value);label.appendChild(select);card.appendChild(label)}
function save(s,field,value){ratings[s.sample_id]={...(ratings[s.sample_id]||{}),sample_id:s.sample_id,model:s.model,voice:s.voice,voice_identity_group:s.voice_identity_group,annotation_provenance:'human_auditory_impression',reviewer:'user_local_browser',updated_utc:new Date().toISOString(),[field]:value};localStorage.setItem(key,JSON.stringify(ratings));document.getElementById('status').textContent='הבחירה נשמרה בדפדפן. ליצירת קובץ, השתמשו בייצוא.';updateStats()}
function updateStats(){document.getElementById('stats').replaceChildren();const m=bundle.metrics,items=[[m.decoded_samples,'דגימות'],[m.models,'מודלים'],[m.provider_voice_groups,'קבוצות קול'],[m.minutes_generated.toFixed(1),'דקות אודיו'],['$'+m.billing.reported_request_cost_sum_usd.toFixed(2),'עלות בקשות מדווחת'],[Object.keys(ratings).length,'דגימות עם תיוג אנושי מקומי']];items.forEach(([n,label])=>{const card=element('div',undefined,'stat');card.append(element('strong',String(n)),element('span',label));document.getElementById('stats').append(card)})}
function filtered(){const model=document.getElementById('model').value,query=document.getElementById('search').value.toLowerCase(),filter=document.getElementById('filter').value;return samples.filter(s=>(!model||s.model===model)&&(!query||(s.voice+' '+s.family).toLowerCase().includes(query))&&(filter!=='unrated'||!ratings[s.sample_id])&&(filter!=='flagged'||Number(s.review_flag_count)>0))}
function render(){const all=filtered();page=Math.min(page,Math.max(0,Math.ceil(all.length/size)-1));const gallery=document.getElementById('gallery');gallery.replaceChildren();document.getElementById('count').textContent=`${all.length} דגימות בתצוגה המסוננת`;document.getElementById('page').textContent=`עמוד ${page+1} מתוך ${Math.max(1,Math.ceil(all.length/size))}`;document.getElementById('previous').disabled=page===0;document.getElementById('next').disabled=(page+1)*size>=all.length;
all.slice(page*size,(page+1)*size).forEach(s=>{const card=element('section',undefined,'card'+(ratings[s.sample_id]?' saved':''));card.append(element('h3',s.voice,'id'),element('div',s.model,'model id'));card.append(element('p',`${Number(s.duration_s).toFixed(2)} שניות · עוצמה ${Number(s.rms_dbfs).toFixed(1)} dBFS`,'small muted'));const audio=element('audio');audio.controls=true;audio.preload='none';audio.src=s.wav_path;card.append(audio);card.append(element('span',Number(s.review_flag_count)>0?'מועמד לבדיקה':'עבר בדיקה אוטומטית',Number(s.review_flag_count)>0?'pill warn':'pill'));
selectField(card,'האם זהו המשפט העברי המבוקש?','hebrew_text_match',[['','בחרו'],['yes','כן'],['no','לא'],['uncertain','לא בטוח']],s);selectField(card,'התרשמות מהקול — לא מין ביולוגי','perceived_voice_presentation',presentation,s);selectField(card,'טווח גיל נתפס — לא גיל אמיתי','perceived_age_band',ages,s);selectField(card,'מובנות','intelligibility',[['','בחרו'],['clear','ברור'],['partly_clear','ברור חלקית'],['unclear','לא ברור']],s);
const label=element('label','הערות'),notes=element('textarea');notes.value=(ratings[s.sample_id]||{}).notes||'';notes.onchange=()=>save(s,'notes',notes.value);label.append(notes);card.append(label);
const details=element('details');details.append(element('summary','הצגת תיוגי הספק והערכות המודל'));const text=`תווית קול של הספק: ${s.provider_gender_label}; תיאור גיל של הספק: ${s.provider_age_label}\nהתרשמות המודל מהקול: ${s.presentation_for_summary}\nאומדן גיל אוטומטי: לא תקף לפילוח — כל הדגימות קיבלו אותה קטגוריה\nתמלול המודל: ${s.transcript}\nהערות בדיקה: ${s.review_reasons||'ללא'}`;details.append(element('p',text,'small notes'));card.append(details);gallery.append(card)})}
const model=document.getElementById('model');[...new Set(samples.map(s=>s.model))].sort().forEach(value=>{const o=element('option',value);o.value=value;model.append(o)});['model','search','filter'].forEach(id=>document.getElementById(id).addEventListener(id==='search'?'input':'change',()=>{page=0;render()}));document.getElementById('previous').onclick=()=>{page--;render()};document.getElementById('next').onclick=()=>{page++;render()};
document.getElementById('export').onclick=()=>{const data={schema_version:1,exported_utc:new Date().toISOString(),scope:'reviewed_synthetic_excerpt_only',ratings:Object.values(ratings)};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=element('a');a.href=url;a.download='synthetic_human_ratings.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
document.getElementById('importButton').onclick=()=>document.getElementById('importFile').click();document.getElementById('importFile').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;const data=JSON.parse(await file.text());if(!Array.isArray(data.ratings))throw new Error('schema');for(const r of data.ratings){if(ids.has(r.sample_id))ratings[r.sample_id]=r}localStorage.setItem(key,JSON.stringify(ratings));updateStats();render();document.getElementById('status').textContent='התיוגים נטענו.'}catch(e){document.getElementById('status').textContent='לא ניתן לקרוא את קובץ התיוגים.'}};
document.getElementById('prompt').textContent=samples[0].text;updateStats();render();
const table=element('table'),head=element('tr');['מודל','קולות','תווית ספק: גברי','תווית ספק: נשי','תווית ספק: נייטרלי','תווית ספק: חסר','אומדן קולי גברי','אומדן קולי נשי'].forEach(text=>head.append(element('th',text)));table.append(head);
[...new Set(samples.map(s=>s.model))].sort().forEach(model=>{const rows=samples.filter(s=>s.model===model),tr=element('tr'),counts=[model,rows.length,rows.filter(s=>s.provider_gender_label==='male').length,rows.filter(s=>s.provider_gender_label==='female').length,rows.filter(s=>s.provider_gender_label==='neutral').length,rows.filter(s=>s.provider_gender_label==='unknown').length,rows.filter(s=>s.presentation_for_summary==='masculine').length,rows.filter(s=>s.presentation_for_summary==='feminine').length];counts.forEach((value,i)=>tr.append(element('td',String(value),i===0?'id':'')));table.append(tr)});document.getElementById('voiceTable').append(table);
</script></main></body></html>'''
page=template.replace('__PAYLOAD__',payload)
(OUT/'review.html').write_text(page,encoding='utf-8')
print('Created offline Hebrew listening workbench:',OUT/'review.html')
